out = r.get("output")
if not isinstance(out, dict):
    raise ValueError("note_file returned something other than an object.")
return dict(out, tool_output=out)

titles = []
for s in similar or []:
    t = s.get("title") if isinstance(s, dict) else None
    if t and t not in titles:
        titles.append(t)
parts = ["Saved as " + str(kind or "note") + " \u201c" + str(title or "") + "\u201d."]
if titles:
    parts.append("Related: " + ", ".join(titles[:3]) + ".")
dates = [str(r.get("occurred_at") or "")[:10] for r in (revisits or []) if isinstance(r, dict)]
dates = [d for d in dates if d]
if dates:
    parts.append("You noted this on " + dates[0] + ".")
for w in warnings or []:
    if isinstance(w, str) and w.strip():
        parts.append(w.strip())
return {"message": " ".join(parts)}

